        public const string BACKSTORY_START = "{=Dramalord149}My childhood was not easy. I grew up an urchin on the streets, cared for by the local gang.";
        public const string BACKSTORY_GENERAL = "{=Dramalord150}The leader fed us scarcely and would send us off to rob and steal. If we we could not bring home enough spoils by end of day, we were beaten.";
        public const string BACKSTORY_FEMALE_1 = "{=Dramalord151}As soon as I grew teats I was sent to the tavern. I had to entertain disgusting men and make them spend their money on drinks.. or on me.";
        public const string BACKSTORY_FEMALE_2 = "{=Dramalord152}Once there was an old, orange faced guy who constantly grabbed me by the... you know... without paying. So I kicked him in the nuts and fled out of the town.";
        public const string BACKSTORY_FEMALE_3 = "{=Dramalord153}Anyway, I figured that it was better to stab than be 'stabbed', so to speak. So, I made it my new business.";
        public const string BACKSTORY_MALE_1 = "{=Dramalord154}As soon as I had a single hair upon my chest I was sent off to the castles as a servant for elderly ladies. I would 'entertain' them while their husbands were off at war.";
        public const string BACKSTORY_MALE_2 = "{=Dramalord155}One night, while 'planting seeds' in the 'old silver forest', the heart of the, uh, forest's owner seemed to simply stop. I panicked, thinking that I would be found to blame. So I fled.";
        public const string BACKSTORY_MALE_3 = "{=Dramalord156}So, the times working with my wood are over, switched to sword and axe instead. Turns out I'm quite good with that too.";
        public const string BACKSTORY_FEMALE_2_REPLY_1 = "{=Dramalord157}Lord Stickyfinger did not deserve any better I suppose.";
        public const string BACKSTORY_FEMALE_2_REPLY_2 = "{=Dramalord158}Ouch! That's quite the punishment.";
        public const string BACKSTORY_MALE_2_REPLY_1 = "{=Dramalord159}It must have been hard being a young buck in old forests.";
        public const string BACKSTORY_MALE_2_REPLY_2 = "{=Dramalord160}Well, young timber hardly belongs in ancient forests, does it?";

