        public const string PERSUASION_MARRIAGE_Q = "{=Dramalord332}This is all so overwhelming... I love you, {PLAYER.NAME}, but are we truly ready?";
        public const string PERSUASION_MARRIAGE_1 = "{=Dramalord333}Love is a journey, and I would see where this road leads us.";
