        public const string QUESTION_POI_DISLIKE_FAIL = "{=Dramalord098}Hmph. You admire {ACTOR1.LINK}? How very disappointing.";
        public const string QUESTION_POI_DISLIKE_SUCCESS = "{=Dramalord099}I completely agree! {ACTOR1.LINK} left a very poor impression on me.";
        public const string QUESTION_POI_DISLIKE_NOCARE = "{=Dramalord100}Well, I do not care for {ACTOR1.LINK} much at all.";
